// MoveIt Official Brand Assets & PDF Utilities
export const MOVEIT_LOGO_BASE64 = 'data:image/png;base64,'

import { jsPDF } from 'jspdf'
import autoTable from 'jspdf-autotable'

export const drawMoveItPdfHeader = (doc: any, title: string, subtitle: string, rightMeta?: { label: string; value: string }[]) => {
  const redColor = [220, 38, 38]
  const darkColor = [15, 23, 42]
  const grayColor = [100, 116, 139]

  // Top Red Brand Accent Bar
  doc.setFillColor(...redColor)
  doc.rect(0, 0, 210, 5, 'F')

  // Real MoveIt Logo from base64
  try {
    doc.addImage(MOVEIT_LOGO_BASE64, 'PNG', 14, 10, 42, 9.35)
  } catch (e) {
    doc.setFont('helvetica', 'bold')
    doc.setFontSize(16)
    doc.setTextColor(...redColor)
    doc.text('move-it', 14, 18)
  }

  doc.setFont('helvetica', 'normal')
  doc.setFontSize(7.5)
  doc.setTextColor(...grayColor)
  doc.text('Premium Moving & Logistics Maastricht B.V.', 14, 23.5)

  // Top Right: Legal & Contact Details
  doc.setFontSize(7.5)
  doc.setTextColor(...grayColor)
  doc.text('MoveIt Maastricht B.V.', 196, 12, { align: 'right' })
  doc.text('Oranjeplein 35D, 6224 KV Maastricht, NL', 196, 16, { align: 'right' })
  doc.text('Email: info@moveitmaastricht.nl | +31 6 21713503', 196, 20, { align: 'right' })
  doc.text('KvK: 84920194 • BTW/VAT: NL863412345B01', 196, 24, { align: 'right' })

  // Divider Line
  doc.setDrawColor(226, 232, 240)
  doc.setLineWidth(0.4)
  doc.line(14, 28, 196, 28)

  // Document Title
  doc.setFont('helvetica', 'bold')
  doc.setFontSize(15)
  doc.setTextColor(...redColor)
  doc.text(title.toUpperCase(), 14, 37)

  doc.setFont('helvetica', 'normal')
  doc.setFontSize(8)
  doc.setTextColor(...grayColor)
  doc.text(subtitle, 14, 42)

  // Right Metadata
  if (rightMeta && rightMeta.length > 0) {
    let yPos = 35
    for (const m of rightMeta) {
      doc.setFont('helvetica', 'bold')
      doc.setFontSize(8)
      doc.setTextColor(...darkColor)
      doc.text(m.label + ': ', 145, yPos)
      doc.setFont('helvetica', 'normal')
      doc.setTextColor(...grayColor)
      doc.text(m.value, 196, yPos, { align: 'right' })
      yPos += 4.5
    }
  }

  return 48
}

export const generateMoveItQuotationPDF = (jobOrLead: any) => {
  try {
    const doc = new jsPDF({
      orientation: 'portrait',
      unit: 'mm',
      format: 'a4'
    })

    const redColor = [220, 38, 38]
    const darkColor = [15, 23, 42]
    const grayColor = [100, 116, 139]
    const lightBg = [248, 250, 252]

    const ref = jobOrLead.ref || ('L-' + String(jobOrLead.id || '1048').slice(0, 8))
    const customer = (jobOrLead.customer || jobOrLead.name || 'Valued Customer').replace(/[\"\']/g, '').trim()
    const phone = jobOrLead.phone && jobOrLead.phone !== 'N/A' ? jobOrLead.phone : (jobOrLead.raw?.form_data?.phone || 'On File')
    const email = jobOrLead.email && jobOrLead.email !== 'N/A' ? jobOrLead.email : (jobOrLead.raw?.form_data?.email || 'On File')
    const movingDate = jobOrLead.movingDate || jobOrLead.shortDate || (jobOrLead.raw?.created_at ? jobOrLead.raw.created_at.split('T')[0] : 'Flexible')
    const fromAddress = jobOrLead.fromFull || jobOrLead.raw?.form_data?.from || (jobOrLead.route ? jobOrLead.route.split('→')[0].trim() : 'Maastricht, NL')
    const toAddress = jobOrLead.toFull || jobOrLead.raw?.form_data?.to || (jobOrLead.route ? jobOrLead.route.split('→')[1].trim() : 'Destination')
    const movePackage = jobOrLead.package || jobOrLead.moveSize || jobOrLead.raw?.form_data?.size || 'Standard Move'
    const floors = jobOrLead.floors || (jobOrLead.raw?.form_data?.pickupFloor ? (jobOrLead.raw.form_data.pickupFloor + ' → ' + (jobOrLead.raw.form_data.deliveryFloor || 'Ground')) : 'Ground Floor')
    const elevator = jobOrLead.elevator || jobOrLead.raw?.form_data?.elevator || 'No'
    const packing = jobOrLead.packing || (jobOrLead.raw?.form_data?.packing === 'yes' ? 'Yes (Full Packing)' : 'Self Packed')
    const assembly = jobOrLead.assembly || (jobOrLead.raw?.form_data?.assembly === 'yes' ? 'Yes (Included)' : 'Not Required')
    const notes = jobOrLead.notes || jobOrLead.raw?.form_data?.notes || ''

    const estRevenue = Number(jobOrLead.estValue || jobOrLead.actual_revenue || jobOrLead.est_revenue || 450)
    const netTotal = Math.round((estRevenue / 1.21) * 100) / 100
    const vatAmount = Math.round((estRevenue - netTotal) * 100) / 100
    const todayStr = new Date().toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' })

    drawMoveItPdfHeader(
      doc,
      'OFFICIAL RELOCATION QUOTATION',
      'MoveIt Maastricht B.V. • Professional Moving Services',
      [
        { label: 'Quote Ref', value: 'QT-2026-' + ref },
        { label: 'Issue Date', value: todayStr },
        { label: 'Validity', value: '30 Days' },
        { label: 'Status', value: jobOrLead.status || 'Active Lead' }
      ]
    )

    doc.setFillColor(...lightBg)
    doc.setDrawColor(226, 232, 240)
    doc.roundedRect(14, 52, 88, 38, 2.5, 2.5, 'FD')

    doc.setFont('helvetica', 'bold')
    doc.setFontSize(8)
    doc.setTextColor(...darkColor)
    doc.text('CLIENT INFORMATION', 18, 58)

    doc.setFont('helvetica', 'normal')
    doc.setFontSize(7.5)
    doc.text('Customer: ' + customer, 18, 64)
    doc.text('Phone: ' + phone, 18, 70)
    doc.text('Email: ' + email, 18, 76)
    doc.text('Source: ' + (jobOrLead.source || 'Direct / Website'), 18, 82)
    doc.text('Priority: ' + (jobOrLead.priority || 'Standard'), 18, 87)

    doc.setFillColor(...lightBg)
    doc.roundedRect(108, 52, 88, 38, 2.5, 2.5, 'FD')

    doc.setFont('helvetica', 'bold')
    doc.setFontSize(8)
    doc.setTextColor(...darkColor)
    doc.text('RELOCATION SPECIFICATION', 112, 58)

    doc.setFont('helvetica', 'normal')
    doc.setFontSize(7.5)
    doc.text('Moving Date: ' + movingDate, 112, 64)
    const pFrom = doc.splitTextToSize('Pickup: ' + fromAddress, 80)
    doc.text(pFrom[0] || ('Pickup: ' + fromAddress), 112, 70)
    const pTo = doc.splitTextToSize('Delivery: ' + toAddress, 80)
    doc.text(pTo[0] || ('Delivery: ' + toAddress), 112, 76)
    doc.text('Move Size / Package: ' + movePackage, 112, 82)
    doc.text('Floors: ' + floors + ' | Elevator: ' + elevator, 112, 87)

    const baseAmount = Math.round(netTotal * 0.70)
    const transitAmount = Math.round(netTotal * 0.18)
    const equipAmount = Math.round((netTotal - baseAmount - transitAmount) * 100) / 100

    const tableRows = [
      [
        '1',
        'Dedicated Moving Crew & Commercial Van (' + movePackage + ')',
        'Loading, secured transit, and careful unloading into designated rooms.',
        '€' + baseAmount.toFixed(2)
      ],
      [
        '2',
        'Route Transit & Fuel Surcharge (' + (jobOrLead.route || 'Direct Route') + ')',
        'Door-to-door transit between pickup and delivery locations.',
        '€' + transitAmount.toFixed(2)
      ],
      [
        '3',
        'Protective Equipment & Blankets',
        'Padded moving blankets, straps, dollies, mattress covers. Packing: ' + packing + '.',
        '€' + equipAmount.toFixed(2)
      ],
      [
        '4',
        'Goods in Transit Insurance Protection',
        'Comprehensive relocation insurance coverage up to €50,000.',
        'INCLUDED'
      ]
    ]

    const autoTableFn = (autoTable as any).default || autoTable
    autoTableFn(doc, {
      startY: 94,
      head: [['#', 'Service Description', 'Details & Scope', 'Amount (Excl. VAT)']],
      body: tableRows,
      theme: 'grid',
      headStyles: {
        fillColor: darkColor,
        textColor: [255, 255, 255],
        fontStyle: 'bold',
        fontSize: 8,
        halign: 'left'
      },
      bodyStyles: {
        fontSize: 7.5,
        textColor: darkColor
      },
      columnStyles: {
        0: { cellWidth: 8, halign: 'center' },
        1: { cellWidth: 62 },
        2: { cellWidth: 78 },
        3: { cellWidth: 34, halign: 'right', fontStyle: 'bold' }
      },
      margin: { left: 14, right: 14 }
    })

    const finalY = (doc as any).lastAutoTable?.finalY || 155

    doc.setFillColor(...lightBg)
    doc.setDrawColor(226, 232, 240)
    doc.roundedRect(114, finalY + 6, 82, 30, 2, 2, 'FD')

    doc.setFont('helvetica', 'normal')
    doc.setFontSize(8)
    doc.setTextColor(...darkColor)
    doc.text('Subtotal (Excl. BTW):', 118, finalY + 13)
    doc.text('€' + netTotal.toFixed(2), 192, finalY + 13, { align: 'right' })

    doc.text('21% Dutch BTW / VAT:', 118, finalY + 19)
    doc.text('€' + vatAmount.toFixed(2), 192, finalY + 19, { align: 'right' })

    doc.setDrawColor(226, 232, 240)
    doc.line(118, finalY + 22, 192, finalY + 22)

    doc.setFont('helvetica', 'bold')
    doc.setFontSize(9.5)
    doc.setTextColor(...redColor)
    doc.text('Total Quotation (EUR):', 118, finalY + 29)
    doc.text('€' + estRevenue.toFixed(2), 192, finalY + 29, { align: 'right' })

    if (notes) {
      doc.setFillColor(254, 243, 199)
      doc.setDrawColor(245, 158, 11)
      doc.roundedRect(14, finalY + 6, 94, 30, 2, 2, 'FD')
      doc.setFont('helvetica', 'bold')
      doc.setFontSize(7.5)
      doc.setTextColor(180, 83, 9)
      doc.text('CUSTOMER NOTES & PREFERENCES:', 18, finalY + 12)
      doc.setFont('helvetica', 'normal')
      doc.setTextColor(30, 41, 59)
      const splitNotes = doc.splitTextToSize(notes, 86)
      doc.text(splitNotes.slice(0, 3), 18, finalY + 18)
    }

    const footerY = Math.max(finalY + 42, 240)
    doc.setDrawColor(226, 232, 240)
    doc.line(14, footerY, 196, footerY)

    doc.setFont('helvetica', 'bold')
    doc.setFontSize(7.5)
    doc.setTextColor(...darkColor)
    doc.text('Payment Terms & Confirmation:', 14, footerY + 5)

    doc.setFont('helvetica', 'normal')
    doc.setFontSize(7)
    doc.setTextColor(...grayColor)
    doc.text('A deposit of 20% secures your relocation date and assigned crew. Balance payable upon delivery completion.', 14, footerY + 9)
    doc.text('Bank: Rabobank Maastricht • IBAN: NL44 RABO 0123 4567 89 • BIC: RABONL2U • KvK: 84920194 • BTW: NL863412345B01', 14, footerY + 13)
    doc.text('MoveIt Maastricht B.V. is certified under Dutch transport regulations. All services subject to AVC/CMR terms.', 14, footerY + 17)

    const safeCustomer = customer.replace(/[^a-zA-Z0-9]/g, '_')
    doc.save('MoveIt_Quotation_' + ref + '_' + safeCustomer + '.pdf')
    return true
  } catch (err) {
    console.error('Error generating quotation PDF:', err)
    return false
  }
}

export const generateMoveItInvoicePDF = (order: any) => {
  try {
    const doc = new jsPDF({
      orientation: 'portrait',
      unit: 'mm',
      format: 'a4'
    })

    const redColor = [220, 38, 38]
    const darkColor = [15, 23, 42]
    const grayColor = [100, 116, 139]
    const lightBg = [248, 250, 252]

    const ref = order.ref || ('J-' + String(order.id || '1101').slice(0, 8))
    const invNumber = 'INV-2026-' + ref
    const customer = (order.customer || order.name || 'Client').replace(/[\"\']/g, '').trim()
    const phone = order.phone && order.phone !== 'N/A' ? order.phone : (order.raw?.form_data?.phone || 'On File')
    const email = order.email && order.email !== 'N/A' ? order.email : (order.raw?.form_data?.email || 'On File')
    const movingDate = order.movingDate || order.shortDate || (order.raw?.created_at ? order.raw.created_at.split('T')[0] : 'Completed')
    const fromAddress = order.fromFull || order.raw?.form_data?.from || (order.route ? order.route.split('→')[0].trim() : 'Maastricht, NL')
    const toAddress = order.toFull || order.raw?.form_data?.to || (order.route ? order.route.split('→')[1].trim() : 'Destination')
    const movePackage = order.package || 'Relocation Service'
    const status = (order.operationalStatus || order.status || 'Confirmed').toUpperCase()

    const rawTotal = Number(order.estValue || order.actual_revenue || order.est_revenue || 450)
    const netTotal = Math.round((rawTotal / 1.21) * 100) / 100
    const vatAmount = Math.round((rawTotal - netTotal) * 100) / 100
    const todayStr = new Date().toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' })

    drawMoveItPdfHeader(
      doc,
      'OFFICIAL TAX INVOICE • FACTUUR',
      'MoveIt Maastricht B.V. • KvK: 84920194 • BTW: NL863412345B01',
      [
        { label: 'Invoice No', value: invNumber },
        { label: 'Invoice Date', value: todayStr },
        { label: 'Job Ref', value: ref },
        { label: 'Payment Status', value: status === 'COMPLETED' ? 'PAID' : status }
      ]
    )

    doc.setFillColor(...lightBg)
    doc.setDrawColor(226, 232, 240)
    doc.roundedRect(14, 52, 88, 38, 2.5, 2.5, 'FD')

    doc.setFont('helvetica', 'bold')
    doc.setFontSize(8)
    doc.setTextColor(...darkColor)
    doc.text('INVOICE TO (CLIENT)', 18, 58)

    doc.setFont('helvetica', 'normal')
    doc.setFontSize(7.5)
    doc.text('Customer Name: ' + customer, 18, 64)
    doc.text('Contact Phone: ' + phone, 18, 70)
    doc.text('Contact Email: ' + email, 18, 76)
    doc.text('Address: ' + fromAddress.slice(0, 42), 18, 82)
    doc.text('Billing Type: ' + (order.type || 'Individual Relocation'), 18, 87)

    doc.setFillColor(...lightBg)
    doc.roundedRect(108, 52, 88, 38, 2.5, 2.5, 'FD')

    doc.setFont('helvetica', 'bold')
    doc.setFontSize(8)
    doc.setTextColor(...darkColor)
    doc.text('SERVICE DETAILS', 112, 58)

    doc.setFont('helvetica', 'normal')
    doc.setFontSize(7.5)
    doc.text('Execution Date: ' + movingDate, 112, 64)
    doc.text('Route: ' + (order.route || 'Direct Route'), 112, 70)
    doc.text('Service Scope: ' + movePackage, 112, 76)
    doc.text('Destination: ' + toAddress.slice(0, 40), 112, 82)
    doc.text('Payment Term: Net 14 Days from invoice date', 112, 87)

    const autoTableFn = (autoTable as any).default || autoTable
    autoTableFn(doc, {
      startY: 94,
      head: [['#', 'Item / Service', 'Category', 'VAT Rate', 'Net Amount (EUR)']],
      body: [
        ['1', 'Relocation & Logistics Service (' + movePackage + ')', 'Moving Services', '21%', '€' + netTotal.toFixed(2)]
      ],
      theme: 'grid',
      headStyles: {
        fillColor: darkColor,
        textColor: [255, 255, 255],
        fontStyle: 'bold',
        fontSize: 8,
        halign: 'left'
      },
      bodyStyles: {
        fontSize: 8,
        textColor: darkColor
      },
      columnStyles: {
        0: { cellWidth: 8, halign: 'center' },
        1: { cellWidth: 85 },
        2: { cellWidth: 40 },
        3: { cellWidth: 20, halign: 'center' },
        4: { cellWidth: 29, halign: 'right', fontStyle: 'bold' }
      },
      margin: { left: 14, right: 14 }
    })

    const finalY = (doc as any).lastAutoTable?.finalY || 120

    doc.setFillColor(...lightBg)
    doc.setDrawColor(226, 232, 240)
    doc.roundedRect(114, finalY + 8, 82, 32, 2, 2, 'FD')

    doc.setFont('helvetica', 'normal')
    doc.setFontSize(8)
    doc.setTextColor(...darkColor)
    doc.text('Subtotal (Excl. BTW):', 118, finalY + 16)
    doc.text('€' + netTotal.toFixed(2), 192, finalY + 16, { align: 'right' })

    doc.text('Dutch BTW (21.00%):', 118, finalY + 22)
    doc.text('€' + vatAmount.toFixed(2), 192, finalY + 22, { align: 'right' })

    doc.setDrawColor(226, 232, 240)
    doc.line(118, finalY + 26, 192, finalY + 26)

    doc.setFont('helvetica', 'bold')
    doc.setFontSize(10)
    doc.setTextColor(...redColor)
    doc.text('Total Due (Incl. BTW):', 118, finalY + 34)
    doc.text('€' + rawTotal.toFixed(2), 192, finalY + 34, { align: 'right' })

    doc.setFillColor(241, 245, 249)
    doc.setDrawColor(203, 213, 225)
    doc.roundedRect(14, finalY + 8, 94, 32, 2, 2, 'FD')

    doc.setFont('helvetica', 'bold')
    doc.setFontSize(8)
    doc.setTextColor(...darkColor)
    doc.text('BANK TRANSFER INSTRUCTIONS:', 18, finalY + 16)

    doc.setFont('helvetica', 'normal')
    doc.setFontSize(7.5)
    doc.setTextColor(51, 65, 85)
    doc.text('Account Name: MoveIt Maastricht B.V.', 18, finalY + 22)
    doc.text('IBAN: NL44 RABO 0123 4567 89 • BIC: RABONL2U', 18, finalY + 27)
    doc.text('Payment Reference: ' + invNumber, 18, finalY + 32)

    const footerY = 245
    doc.setDrawColor(226, 232, 240)
    doc.line(14, footerY, 196, footerY)

    doc.setFont('helvetica', 'bold')
    doc.setFontSize(7.5)
    doc.setTextColor(...darkColor)
    doc.text('Thank you for choosing MoveIt Maastricht!', 14, footerY + 5)

    doc.setFont('helvetica', 'normal')
    doc.setFontSize(7)
    doc.setTextColor(...grayColor)
    doc.text('For billing inquiries, please contact info@moveitmaastricht.nl or call +31 6 21713503.', 14, footerY + 9)
    doc.text('All transport and storage contracts governed by Dutch general relocation conditions (AVC/CMR).', 14, footerY + 13)

    const safeCustomer = customer.replace(/[^a-zA-Z0-9]/g, '_')
    doc.save('MoveIt_Invoice_' + ref + '_' + safeCustomer + '.pdf')
    return true
  } catch (err) {
    console.error('Error generating invoice PDF:', err)
    return false
  }
}
